'use client';
import React from 'react';

import * as Picker from 'emoji-picker-react/primitives';

// Bottom navigation bar with the M3 pill indicator on the active tab
// ([aria-selected="true"]); circular emoji state layers.
export type PickerExampleProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ComponentType<Picker.RootProps>;
  className?: string;
};

export function PickerExample({
  Root: RootComponent = Picker.Root,
  className,
}: PickerExampleProps) {
  return (
    <RootComponent
      appearance="default"
      className={className}
      searchPlaceholder="Search emoji"
    >
      <Picker.Search />
      <Picker.Viewport>
        <Picker.List />
        <Picker.Empty />
      </Picker.Viewport>
      <Picker.CategoryNav />
    </RootComponent>
  );
}

/* Material 3 — tonal surface, 28px container radius, pill search bar and a
   bottom navigation bar with a pill active indicator. */
/* Picker styles — the source of truth for every stack variant. */
.m3-picker {
  --m3-primary: #6750a4;
  --m3-on-surface: #1d1b20;
  --m3-on-surface-variant: #49454f;
  --m3-surface: #f7f2fa;
  --m3-surface-container: #ece6f0;
  --m3-secondary-container: #e8def8;
  --epr-bg-color: var(--m3-surface);
  --epr-text-color: var(--m3-on-surface-variant);
  --epr-highlight-color: var(--m3-primary);
  --epr-hover-bg-color: rgb(103 80 164 / 8%);
  --epr-focus-bg-color: rgb(103 80 164 / 12%);
  --epr-search-input-bg-color: var(--m3-surface-container);
  --epr-search-input-bg-color-active: var(--m3-surface-container);
  --epr-search-border-color: transparent;
  --epr-search-border-color-active: transparent;
  --epr-search-input-height: 48px;
  --epr-search-input-border-radius: 28px;
  --epr-search-input-padding: 0 20px 0 48px;
  --epr-search-input-text-color: var(--m3-on-surface);
  --epr-search-input-placeholder-color: var(--m3-on-surface-variant);
  --epr-category-label-bg-color: rgb(247 242 250 / 94%);
  --epr-category-label-text-color: var(--m3-primary);
  --epr-category-label-height: 36px;
  --epr-category-icon-active-color: #21005d;
  --epr-category-icon-inactive-color: var(--m3-on-surface-variant);
  --epr-category-navigation-button-size: 24px;
  --epr-emoji-variation-picker-bg-color: var(--m3-surface-container);
  --epr-emoji-size: 30px;
  --epr-emoji-padding: 6px;
  --epr-horizontal-padding: 16px;
  width: 380px;
  height: 480px;
  border-radius: 28px;
  background: var(--m3-surface);
  box-shadow:
    0 1px 3px rgb(0 0 0 / 30%),
    0 4px 8px 3px rgb(0 0 0 / 15%);
  font-family: Roboto, 'Google Sans', 'Segoe UI', Arial, sans-serif;
}
.m3-picker [data-epr-part='search'] > * {
  padding: 16px 16px 8px;
}
.m3-picker [data-epr-part='category-label'] {
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.1px;
  text-transform: none;
}
.m3-picker [data-epr-part='emoji'] {
  border-radius: 50%;
}
.m3-picker [data-epr-part='category-nav'] {
  background: var(--m3-surface-container);
}
.m3-picker [data-epr-part='category-nav'] > * {
  padding: 12px 8px 14px;
}
.m3-picker [data-epr-part='category-tab'] {
  width: 36px;
  border-radius: 16px;
}
.m3-picker [data-epr-part='category-tab'][aria-selected='true'] {
  background-color: var(--m3-secondary-container);
}
.m3-picker [data-epr-part='category-tab']:focus::before {
  border-radius: 16px;
}

